def policy(obs, P):
    x = obs[0]
    v = obs[1]
    if x <= P["p0"]:
        return 1
    if x >= P["x1"] and v <= P["v2"]:
        return 0
    if v > P["v_low"] and v <= P["v_high"] and x <= P["x0"]:
        return 0
    if v > P["v_high"] and v <= P["v3"] and x <= P["x2"]:
        return 0
    if x >= P["x3"] and x <= P["x4"] and v >= P["v4"] and v <= P["v5"]:
        return 1
    return 2
